  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "In this systematic review and meta-analysis, we examined the evidence on transjugular intrahepatic portosystemic shunt (TIPS) as a bridge to elective and emergency surgery in cirrhotic patients. We aimed to assess the perioperative characteristics, management approaches, and outcomes of this intervention, which is used to achieve portal decompression and enable the safe performance of elective and emergent surgery.",
      "reason": "The review's objectives are explicitly stated (examining TIPS as a bridge to elective and emergency surgery; assessing perioperative characteristics, management approaches, and outcomes), but they are not framed using an explicit question-formulation framework (e.g., PICO or similar)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Then, a DerSimonian and Laird random-effects meta-analysis was performed to assess the overall outcomes of TIPS compared to non-TIPS groups.",
      "reason": "The planned comparison (TIPS versus non-TIPS groups) is stated, indicating an intervention comparison was planned, but the review does not present this using a full PICO (Population, Intervention, Comparator, Outcome) or an explicit PICO-format specification in the provided evidence."
    }
  ],
  "confidence": 80
}

